begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email)values('d1000000-0000-0000-0000-000000000001','wa-owner-a@test.invalid'),('d1000000-0000-0000-0000-000000000002','wa-owner-b@test.invalid');
insert into public.tenants(id,name,slug)values('d2000000-0000-0000-0000-000000000001','WA A','wa-onboard-a'),('d2000000-0000-0000-0000-000000000002','WA B','wa-onboard-b');
insert into public.properties(id,tenant_id,name,property_type)values('d3000000-0000-0000-0000-000000000001','d2000000-0000-0000-0000-000000000001','WA Hotel A','hotel'),('d3000000-0000-0000-0000-000000000002','d2000000-0000-0000-0000-000000000002','WA Hotel B','hotel');
insert into public.tenant_memberships(tenant_id,user_id,role)values('d2000000-0000-0000-0000-000000000001','d1000000-0000-0000-0000-000000000001','owner'),('d2000000-0000-0000-0000-000000000002','d1000000-0000-0000-0000-000000000002','owner');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select ok(public.whatsapp_setup_context('d3000000-0000-0000-0000-000000000001')->'connection'='null'::jsonb,'administrator sees own setup');
select throws_ok($$select public.whatsapp_setup_context('d3000000-0000-0000-0000-000000000002')$$,'42501',null,'other hotel setup denied');
select set_config('test.wa_session',public.whatsapp_setup_begin('d3000000-0000-0000-0000-000000000001')::text,true);
select throws_ok($$select public.whatsapp_delivery_credential('managed:d3000000-0000-0000-0000-000000000001')$$,'42501',null,'clients cannot retrieve ciphertext');
reset role;set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select public.whatsapp_setup_claim(current_setting('test.wa_session')::uuid,'d1000000-0000-0000-0000-000000000002')$$,'42501',null,'session bound to initiating user');
select is(public.whatsapp_setup_claim(current_setting('test.wa_session')::uuid,'d1000000-0000-0000-0000-000000000001'),'d3000000-0000-0000-0000-000000000001'::uuid,'backend claims expected hotel');
select throws_ok($$select public.whatsapp_setup_claim(current_setting('test.wa_session')::uuid,'d1000000-0000-0000-0000-000000000001')$$,'42501',null,'session cannot repeat external onboarding');
select lives_ok($$select public.whatsapp_setup_commit(current_setting('test.wa_session')::uuid,'d1000000-0000-0000-0000-000000000001','12345670001','12345670002','+911234567890',repeat('x',80))$$,'backend saves scoped authorization');
select is(public.whatsapp_delivery_credential('managed:d3000000-0000-0000-0000-000000000001'),repeat('x',80),'worker retrieves active encrypted credential');
select is(public.whatsapp_delivery_credential('managed:d3000000-0000-0000-0000-000000000002'),null,'other reference has no credential');
select throws_ok($$select public.whatsapp_setup_commit(current_setting('test.wa_session')::uuid,'d1000000-0000-0000-0000-000000000001','12345670001','12345670002','+911234567890',repeat('x',80))$$,'42501',null,'committed session cannot replay');
reset role;set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.connect_whatsapp('d3000000-0000-0000-0000-000000000001','12345670001','12345670002','+911234567890','manual-bypass')$$,'42501',null,'manual RPC cannot overwrite managed credential');
select lives_ok($$select public.whatsapp_setup_disconnect('d3000000-0000-0000-0000-000000000001')$$,'administrator can disconnect');
select is((public.whatsapp_setup_context('d3000000-0000-0000-0000-000000000001')->'connection'->>'status'),'disabled','disconnect preserves disabled connection');
select set_config('test.wa_session',public.whatsapp_setup_begin('d3000000-0000-0000-0000-000000000001')::text,true);
reset role;set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(public.whatsapp_delivery_credential('managed:d3000000-0000-0000-0000-000000000001'),null,'disconnect deletes saved token');
select public.whatsapp_setup_claim(current_setting('test.wa_session')::uuid,'d1000000-0000-0000-0000-000000000001');
select throws_ok($$select public.whatsapp_setup_commit(current_setting('test.wa_session')::uuid,'d1000000-0000-0000-0000-000000000001','12345670003','12345670002','+911234567890',repeat('x',80))$$,'22023',null,'reconnect cannot reassign sender history');
select lives_ok($$select public.whatsapp_setup_commit(current_setting('test.wa_session')::uuid,'d1000000-0000-0000-0000-000000000001','12345670001','12345670002','+911234567890',repeat('y',80))$$,'same sender reconnect restores credential');
reset role;set local role authenticated;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select set_config('test.wa_session_b',public.whatsapp_setup_begin('d3000000-0000-0000-0000-000000000002')::text,true);
select throws_ok($$select public.whatsapp_setup_disconnect('d3000000-0000-0000-0000-000000000001')$$,'42501',null,'other administrator cannot disconnect hotel');
reset role;set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select public.whatsapp_setup_claim(current_setting('test.wa_session_b')::uuid,'d1000000-0000-0000-0000-000000000002');
select throws_ok($$select public.whatsapp_setup_commit(current_setting('test.wa_session_b')::uuid,'d1000000-0000-0000-0000-000000000002','12345670001','12345670002','+911234567890',repeat('z',80))$$,'23505',null,'sender cannot be attached to two hotels');
reset role;
update public.tenants set status='suspended'where id='d2000000-0000-0000-0000-000000000001';
set local role service_role;
select is(public.whatsapp_delivery_credential('managed:d3000000-0000-0000-0000-000000000001'),null,'suspension prevents token retrieval');
reset role;
select * from finish();
rollback;
